"""Command-line grammar and diagnostics for the graphing application."""
import math
import os
import re
import struct
import sys
from dataclasses import dataclass, field


HELP = """Ping, but with a graph.

Usage: {name} [OPTIONS] [HOSTS_OR_COMMANDS]...

Arguments:
  [HOSTS_OR_COMMANDS]...  Hosts or IPs to ping, or commands to run if --cmd is provided. Can use cloud shorthands like aws:eu-west-1

Options:
      --cmd
          Graph the execution time for a list of commands rather than pinging hosts
  -n, --watch-interval <WATCH_INTERVAL>
          Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5
  -b, --buffer <BUFFER>
          Determines the number of seconds to display in the graph [default: 30]
  -4
          Resolve ping targets to IPv4 address
  -6
          Resolve ping targets to IPv6 address
  -i, --interface <INTERFACE>
          Interface to use when pinging
  -s, --simple-graphics

      --vertical-margin <VERTICAL_MARGIN>
          Vertical margin around the graph (top and bottom) [default: 1]
      --horizontal-margin <HORIZONTAL_MARGIN>
          Horizontal margin around the graph (left and right) [default: 0]
  -c, --color <color>
          Assign color to a graph entry.

          This option can be defined more than once as a comma separated string, and the
          order which the colors are provided will be matched against the hosts or
          commands passed to gping.

          Hexadecimal RGB color codes are accepted in the form of '#RRGGBB' or the
          following color names: 'black', 'red', 'green', 'yellow', 'blue', 'magenta',
          'cyan', 'gray', 'dark-gray', 'light-red', 'light-green', 'light-yellow',
          'light-blue', 'light-magenta', 'light-cyan', and 'white'
      --clear
          Clear the graph from the terminal after closing the program
      --ping-args [<PING_ARGS>...]
          Extra arguments to pass to `ping`. These are platform dependent
  -h, --help
          Print help
  -V, --version
          Print version
"""
VERSION = 'gping 1.20.1\n'
LONG_VERSION = VERSION + '''commit_hash: 42449c03
build_time: 2026-06-11 22:08:42 +00:00
build_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu
'''
FOOTER = "For more information, try '--help'.\n"
PARAMS = {
    'watch-interval': 'WATCH_INTERVAL', 'buffer': 'BUFFER',
    'interface': 'INTERFACE', 'vertical-margin': 'VERTICAL_MARGIN',
    'horizontal-margin': 'HORIZONTAL_MARGIN', 'color': 'color',
}
FLAGS = ['cmd', '4', '6', 'simple-graphics', 'clear', 'help', 'version']
LONGS = ['cmd', 'watch-interval', 'buffer', 'interface', 'simple-graphics',
         'vertical-margin', 'horizontal-margin', 'color', 'clear',
         'ping-args', 'help', 'version']
SHORTS = {'n': 'watch-interval', 'b': 'buffer', '4': '4', '6': '6',
          'i': 'interface', 's': 'simple-graphics', 'c': 'color',
          'h': 'help', 'V': 'version'}


def option_spelling(key):
    if key in PARAMS:
        return '--' + key + ' <' + PARAMS[key] + '>'
    if key == 'ping-args':
        return '--ping-args [<PING_ARGS>...]'
    return ('-' if key in ('4', '6') else '--') + key


class Exit(Exception):
    def __init__(self, code, message='', stdout=False):
        self.code = code
        self.message = message
        self.stdout = stdout


def fail(message):
    raise Exit(1, 'Error: ' + message + '\n')


def as_f32(value):
    try:
        return struct.unpack('f', struct.pack('f', value))[0]
    except OverflowError:
        return math.copysign(math.inf, value)


@dataclass
class Options:
    hosts: list = field(default_factory=list)
    cmd: bool = False
    interval: float = None
    buffer: int = 30
    ipv4: bool = False
    ipv6: bool = False
    interface: str = None
    simple: bool = False
    vertical_margin: int = 1
    horizontal_margin: int = 0
    colors: list = field(default_factory=list)
    clear: bool = False
    ping_args: list = field(default_factory=list)

    def interval_ms(self):
        seconds = self.interval
        if seconds is None:
            seconds = as_f32(.5 if self.cmd else .2)
        value = as_f32(seconds * 1000)
        if math.isnan(value) or value <= 0:
            return 0
        if value >= 18446744073709551615:
            return 18446744073709551615
        return int(value)


def similarity(a, b):
    """A short-string transposition-tolerant spelling score."""
    if a == b:
        return 1.0
    r = max(len(a), len(b)) // 2 - 1
    aa = [False] * len(a)
    bb = [False] * len(b)
    for i, ch in enumerate(a):
        for j in range(max(0, i-r), min(len(b), i+r+1)):
            if not bb[j] and b[j] == ch:
                aa[i] = True
                bb[j] = True
                break
    n = sum(aa)
    if not n:
        return 0.0
    x = [c for c, m in zip(a, aa) if m]
    y = [c for c, m in zip(b, bb) if m]
    trans = sum(c != d for c, d in zip(x, y)) / 2
    score = (n/len(a) + n/len(b) + (n-trans)/n) / 3
    prefix = 0
    for c, d in zip(a[:4], b[:4]):
        if c != d:
            break
        prefix += 1
    if score > .7:
        score += prefix*.1*(1-score)
    return score


class Parser:
    def __init__(self, name):
        self.name = name
        self.opts = Options()
        self.seen = []

    def usage(self, keys=None, required_hosts=False):
        if keys is None:
            part = '[OPTIONS]'
        else:
            part = ' '.join(option_spelling(k) for k in keys)
        host = '<HOSTS_OR_COMMANDS>...' if required_hosts else '[HOSTS_OR_COMMANDS]...'
        return 'Usage: ' + self.name + (' ' + part if part else '') + ' ' + host + '\n'

    def diagnostic(self, message, usage=None, tip=None):
        text = 'error: ' + message + '\n\n'
        if tip:
            text += '  tip: ' + tip + '\n\n'
        if usage is not None:
            text += usage + '\n'
        text += FOOTER
        raise Exit(2, text)

    def unknown(self, name):
        guess = None
        if name.startswith('--'):
            scores = [(similarity(name[2:], x), x) for x in LONGS]
            val, possible = max(scores)
            if val > .8:
                guess = possible
        if guess:
            self.diagnostic("unexpected argument '%s' found" % name,
                            self.usage([guess]),
                            "a similar argument exists: '--%s'" % guess)
        self.diagnostic("unexpected argument '%s' found" % name,
                        self.usage(),
                        "to pass '%s' as a value, use '-- %s'" % (name, name))

    def missing(self, key):
        self.diagnostic("a value is required for '%s' but none was supplied" % option_spelling(key))

    def invalid(self, key, raw, why):
        self.diagnostic("invalid value '%s' for '%s': %s" % (raw, option_spelling(key), why))

    def number(self, key, raw):
        if key == 'watch-interval':
            if not raw:
                self.invalid(key, raw, 'cannot parse float from empty string')
            pattern = r'[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)'
            if re.fullmatch(pattern, raw, re.I) is None:
                self.invalid(key, raw, 'invalid float literal')
            return as_f32(float(raw))
        if not raw:
            self.invalid(key, raw, 'cannot parse integer from empty string')
        margin = key.endswith('margin')
        if re.fullmatch(r'[+-]?[0-9]+' if margin else r'\+?[0-9]+', raw) is None:
            self.invalid(key, raw, 'invalid digit found in string')
        n = int(raw)
        if margin:
            if n < -9223372036854775808:
                self.invalid(key, raw, 'number too small to fit in target type')
            if n > 9223372036854775807:
                self.invalid(key, raw, 'number too large to fit in target type')
            if n < 0 or n > 65535:
                self.invalid(key, raw, '%d is not in 0..=65535' % n)
        elif n > 18446744073709551615:
            self.invalid(key, raw, 'number too large to fit in target type')
        return n

    def add(self, key, value=None, long_form=False):
        if key in self.seen and key not in ('color', 'ping-args'):
            self.diagnostic("the argument '%s' cannot be used multiple times" % option_spelling(key), self.usage())
        if key not in self.seen:
            self.seen.append(key)
        if key == 'help':
            raise Exit(0, HELP.format(name=self.name), True)
        if key == 'version':
            raise Exit(0, LONG_VERSION if long_form else VERSION, True)
        if key == 'color':
            self.opts.colors.extend(value.split(','))
        elif key == 'ping-args':
            self.opts.ping_args.extend(value)
        elif key in ('watch-interval', 'buffer', 'vertical-margin', 'horizontal-margin'):
            n = self.number(key, value)
            setattr(self.opts, 'interval' if key == 'watch-interval' else key.replace('-', '_'), n)
        else:
            dest = {'4': 'ipv4', '6': 'ipv6', 'simple-graphics': 'simple'}.get(key, key)
            setattr(self.opts, dest, value if key == 'interface' else True)

    def parse(self, argv):
        i = 0
        while i < len(argv):
            arg = argv[i]
            if arg == '--':
                self.opts.hosts.extend(argv[i+1:])
                break
            if arg.startswith('--'):
                rawkey, eq, val = arg[2:].partition('=')
                if rawkey not in LONGS:
                    self.unknown('--'+rawkey)
                key = rawkey
                if key == 'ping-args':
                    self.add(key, [val] if eq else argv[i+1:])
                    if not eq:
                        break
                elif key in PARAMS:
                    if not eq:
                        if i+1 >= len(argv):
                            self.missing(key)
                        nxt = argv[i+1]
                        if nxt.startswith('-') and nxt != '-':
                            self.check_missing_flag(key, nxt)
                        i += 1
                        val = argv[i]
                    self.add(key, val, True)
                else:
                    if eq:
                        self.diagnostic("unexpected value '%s' for '%s' found; no more were expected" % (val, option_spelling(key)), self.usage([key]))
                    self.add(key, long_form=True)
            elif arg.startswith('-') and arg != '-':
                j = 1
                while j < len(arg):
                    ch = arg[j]
                    if ch not in SHORTS:
                        self.unknown('-'+ch)
                    key = SHORTS[ch]
                    if key in PARAMS:
                        if j+1 < len(arg):
                            val = arg[j+1:]
                            if val.startswith('='):
                                val = val[1:]
                        else:
                            if i+1 >= len(argv):
                                self.missing(key)
                            nxt = argv[i+1]
                            if nxt.startswith('-') and nxt != '-':
                                self.check_missing_flag(key, nxt)
                            i += 1
                            val = argv[i]
                        self.add(key, val)
                        break
                    self.add(key)
                    j += 1
            else:
                self.opts.hosts.append(arg)
            i += 1
        pairs = [('4','6'), ('cmd','ping-args')]
        conflicts = []
        for a, b in pairs:
            if a in self.seen and b in self.seen:
                if self.seen.index(a) > self.seen.index(b):
                    a,b = b,a
                conflicts.append((self.seen.index(a), a, b))
        if conflicts:
            _, a, b = min(conflicts)
            keys = [k for k in self.seen if k != b]
            # Conflicting pairs beyond the first do not become usage requirements.
            for c, d in pairs:
                if c in keys and d in keys:
                    keys.remove(d if keys.index(c)<keys.index(d) else c)
            self.diagnostic("the argument '%s' cannot be used with '%s'" % (option_spelling(a), option_spelling(b)), self.usage(keys, bool(self.opts.hosts)))
        return self.opts

    def check_missing_flag(self, key, arg):
        if arg == '--' or (arg.startswith('--') and arg[2:].split('=')[0] in LONGS) or (len(arg)>1 and not arg.startswith('--') and arg[1] in SHORTS):
            self.missing(key)
        self.unknown(arg.split('=')[0] if arg.startswith('--') else arg[:2])


def parse(argv=None):
    return Parser(os.path.basename(sys.argv[0])).parse(sys.argv[1:] if argv is None else argv)
PY"}

