    if score > .7:
        score += prefix*.1*(1-score)
    return score


class Parser:
    def __init__(self, name):
        self.name = name
        self.opts = Options()
        self.seen = []

    def usage(self, keys=None, required_hosts=False):
        if keys is None:
            part = '[OPTIONS]'
        else:
            part = ' '.join(option_spelling(k) for k in keys)
        host = '<HOSTS_OR_COMMANDS>...' if required_hosts else '[HOSTS_OR_COMMANDS]...'
        return 'Usage: ' + self.name + (' ' + part if part else '') + ' ' + host + '\n'

    def diagnostic(self, message, usage=None, tip=None):
        text = 'error: ' + message + '\n\n'
        if tip:
            text += '  tip: ' + tip + '\n\n'
        if usage is not None:
            text += usage + '\n'
        text += FOOTER
        raise Exit(2, text)

    def unknown(self, name):
        guess = None
        if name.startswith('--'):
            scores = [(similarity(name[2:], x), x) for x in LONGS]
            val, possible = max(scores)
            if val > .8:
                guess = possible
        if guess:
            self.diagnostic("unexpected argument '%s' found" % name,
                            self.usage([guess]),
                            "a similar argument exists: '--%s'" % guess)
        self.diagnostic("unexpected argument '%s' found" % name,
                        self.usage(),
                        "to pass '%s' as a value, use '-- %s'" % (name, name))

    def missing(self, key):
        self.diagnostic("a value is required for '%s' but none was supplied" % option_spelling(key))

    def invalid(self, key, raw, why):
        self.diagnostic("invalid value '%s' for '%s': %s" % (raw, option_spelling(key), why))

    def number(self, key, raw):
        if key == 'watch-interval':
            if not raw:
                self.invalid(key, raw, 'cannot parse float from empty string')
            pattern = r'[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)'
            if re.fullmatch(pattern, raw, re.I) is None:
                self.invalid(key, raw, 'invalid float literal')
            return as_f32(float(raw))
        if not raw:
            self.invalid(key, raw, 'cannot parse integer from empty string')
        margin = key.endswith('margin')
        if re.fullmatch(r'[+-]?[0-9]+' if margin else r'\+?[0-9]+', raw) is None:
            self.invalid(key, raw, 'invalid digit found in string')
        n = int(raw)
        if margin:
            if n < -9223372036854775808:
                self.invalid(key, raw, 'number too small to fit in target type')
            if n > 9223372036854775807:
                self.invalid(key, raw, 'number too large to fit in target type')
            if n < 0 or n > 65535:
                self.invalid(key, raw, '%d is not in 0..=65535' % n)
        elif n > 18446744073709551615:
            self.invalid(key, raw, 'number too large to fit in target type')
        return n

    def add(self, key, value=None, long_form=False):
        if key in self.seen and key not in ('color', 'ping-args'):
            self.diagnostic("the argument '%s' cannot be used multiple times" % option_spelling(key), self.usage())
        if key not in self.seen:
            self.seen.append(key)
        if key == 'help':
            raise Exit(0, HELP.format(name=self.name), True)
        if key == 'version':
            raise Exit(0, LONG_VERSION if long_form else VERSION, True)
        if key == 'color':
            self.opts.colors.extend(value.split(','))
        elif key == 'ping-args':
            self.opts.ping_args.extend(value)
        elif key in ('watch-interval', 'buffer', 'vertical-margin', 'horizontal-margin'):
            n = self.number(key, value)
            setattr(self.opts, 'interval' if key == 'watch-interval' else key.replace('-', '_'), n)
        else:
            dest = {'4': 'ipv4', '6': 'ipv6', 'simple-graphics': 'simple'}.get(key, key)
            setattr(self.opts, dest, value if key == 'interface' else True)

    def parse(self, argv):
        i = 0
        while i < len(argv):
            arg = argv[i]
            if arg == '--':
                self.opts.hosts.extend(argv[i+1:])
                break
            if arg.startswith('--'):
                rawkey, eq, val = arg[2:].partition('=')
                if rawkey not in LONGS:
                    self.unknown('--'+rawkey)
                key = rawkey
                if key == 'ping-args':
                    self.add(key, [val] if eq else argv[i+1:])
                    if not eq:
                        break
                elif key in PARAMS:
                    if not eq:
                        if i+1 >= len(argv):
                            self.missing(key)
                        nxt = argv[i+1]
                        if nxt.startswith('-') and nxt != '-':
                            self.check_missing_flag(key, nxt)
                        i += 1
                        val = argv[i]
                    self.add(key, val, True)
                else:
                    if eq:
                        self.diagnostic("unexpected value '%s' for '%s' found; no more were expected" % (val, option_spelling(key)), self.usage([key]))
                    self.add(key, long_form=True)
            elif arg.startswith('-') and arg != '-':
                j = 1
                while j < len(arg):
                    ch = arg[j]
                    if ch not in SHORTS:
                        self.unknown('-'+ch)
                    key = SHORTS[ch]
                    if key in PARAMS:
                        if j+1 < len(arg):
                            val = arg[j+1:]
                            if val.startswith('='):
                                val = val[1:]
                        else:
                            if i+1 >= len(argv):
                                self.missing(key)
                            nxt = argv[i+1]
                            if nxt.startswith('-') and nxt != '-':
                                self.check_missing_flag(key, nxt)
                            i += 1
                            val = argv[i]
                        self.add(key, val)
                        break
                    self.add(key)
                    j += 1
            else:
                self.opts.hosts.append(arg)
            i += 1
        pairs = [('4','6'), ('cmd','ping-args')]
        conflicts = []
        for a, b in pairs:
            if a in self.seen and b in self.seen:
                if self.seen.index(a) > self.seen.index(b):
                    a,b = b,a
                conflicts.append((self.seen.index(a), a, b))
        if conflicts:
            _, a, b = min(conflicts)
            keys = [k for k in self.seen if k != b]
            # Conflicting pairs beyond the first do not become usage requirements.
            for c, d in pairs:
                if c in keys and d in keys:
                    keys.remove(d if keys.index(c)<keys.index(d) else c)
            self.diagnostic("the argument '%s' cannot be used with '%s'" % (option_spelling(a), option_spelling(b)), self.usage(keys, bool(self.opts.hosts)))
        return self.opts

    def check_missing_flag(self, key, arg):
        if arg == '--' or (arg.startswith('--') and arg[2:].split('=')[0] in LONGS) or (len(arg)>1 and not arg.startswith('--') and arg[1] in SHORTS):
            self.missing(key)
        self.unknown(arg.split('=')[0] if arg.startswith('--') else arg[:2])


def parse(argv=None):
    return Parser(os.path.basename(sys.argv[0])).parse(sys.argv[1:] if argv is None else argv)
