"""Cell-based ANSI terminal renderer, including dot and braille charts."""
import math
import time
import unicodedata

from model import duration

ESC = '\x1b['
RESET = ESC+'39m'+ESC+'49m'+ESC+'0m'


def color_escape(color):
    if color is None:
        return ESC+'39;49m'
    if isinstance(color, tuple):
        return ESC+'38;2;%d;%d;%d;49m' % color
    return ESC+'38;5;%d;49m' % color


def char_width(ch):
    if ch in '\n\r\t' or ord(ch) < 32 or 127 <= ord(ch) < 160:
        return 0
    if unicodedata.combining(ch):
        return 0
    return 2 if unicodedata.east_asian_width(ch) in ('W', 'F') else 1


def text_width(text):
    return sum(char_width(c) for c in text)


def clipped(text, width, from_right=False):
    if width <= 0:
        return ''
    chars = []
    used = 0
    source = reversed(text) if from_right else text
    for ch in source:
        if ch in '\n\r':
            break
        n = char_width(ch)
        if used + n > width:
            break
        if n == 0:
            if unicodedata.combining(ch) and chars:
                chars.append(ch)
            continue
        chars.append(ch)
        used += n
    if from_right:
        chars.reverse()
    return ''.join(chars)


class Cells:
    def __init__(self, width, height):
        self.width, self.height = width, height
        self.data = [[(' ', None) for _ in range(width)] for _ in range(height)]

    def put(self, x, y, ch, color=None):
        if 0 <= y < self.height and 0 <= x < self.width:
            self.data[y][x] = (ch, color)

    def text(self, x, y, text, color=None, width=None, pad=False, align='left'):
        if not 0 <= y < self.height:
            return
        if width is None:
            width = self.width-x
        width = max(0, min(width, self.width-x))
        text = clipped(text, width, align == 'right')
        n = text_width(text)
        offset = width-n if align == 'right' else (width-n)//2 if align == 'center' else 0
        if pad:
            for pos in range(x, x+width):
                self.put(pos, y, ' ', color)
        pos = x+offset
        for ch in text:
            cw = char_width(ch)
            if cw == 0:
                if pos > x:
                    prev, fg = self.data[y][pos-1]
                    self.put(pos-1, y, prev+ch, fg)
                continue
            self.put(pos, y, ch, color)
            for j in range(1, cw):
                self.put(pos+j, y, '', color)
            pos += cw


class Plot:
    def __init__(self, width, height, simple):
        self.width, self.height = width, height
        self.simple = simple
        self.pw = width if simple else width*2
        self.ph = height if simple else height*4
        self.bits = [[0]*width for _ in range(height)]
        self.colors = [[None]*width for _ in range(height)]

    def pixel(self, x, y, color):
        if not (0 <= x < self.pw and 0 <= y < self.ph):
            return
        if self.simple:
            cx, cy, bit = x, y, 1
        else:
            cx, cy = x//2, y//4
            bit = ((1, 2, 4, 64), (8, 16, 32, 128))[x%2][y%4]
        self.bits[cy][cx] |= bit
