    def line(self, a, b, color):
        if a is None or b is None:
            return
        x0,y0 = a
        x1,y1 = b
        dx, dy = abs(x1-x0), -abs(y1-y0)
        sx, sy = 1 if x0 < x1 else -1, 1 if y0 < y1 else -1
        err = dx+dy
        for _ in range(dx-dy+1):
            self.pixel(x0, y0, color)
            if x0 == x1 and y0 == y1:
                break
            e2 = err*2
            if e2 >= dy:
                err += dy
                x0 += sx
            if e2 <= dx:
                err += dx
                y0 += sy

    def render(self, grid, x, y):
        for j,row in enumerate(self.bits):
            for i,bits in enumerate(row):
                if bits:
                    grid.put(x+i, y+j, '•' if self.simple else chr(0x2800+bits), self.colors[j][i])


