        if h >= 3:
            grid.put(axis_x,y+ph,'└',7)
            grid.text(axis_x+1,y+ph,'─'*pw,7,pw)
        for i,label in enumerate(ylabels):
            yy = y+ph-1 - (i*(ph-1)//6)
