"""Process sampling and the interactive terminal lifecycle."""
import errno
import fcntl
import ipaddress
import json
import math
import os
import queue
import re
import select
import signal
import struct
import subprocess
import sys
import termios
import threading
import time
import tty

from cli import Exit, as_f32, fail
from display import Renderer, ESC


def os_error(error):
    n = getattr(error, 'errno', None) or errno.EIO
    return '%s (os error %d)' % (os.strerror(n), n)


def rust_debug_lines(data):
    text = data.decode('utf-8', errors='replace')
    # splitlines differs from a byte-oriented lines reader for Unicode separators.
    vals = text.split('\n')
    if vals and vals[-1] == '':
        vals.pop()
    vals = [s[:-1] if s.endswith('\r') else s for s in vals]
    return '['+', '.join(json.dumps(v,ensure_ascii=False) for v in vals)+']'


def ping_arguments(target, options, variant):
    try:
        v6 = isinstance(ipaddress.ip_address(target.name), ipaddress.IPv6Address)
    except ValueError:
        v6 = False
    program = 'ping6' if options.ipv6 or v6 else 'ping'
    seconds = as_f32(as_f32(float(options.interval_ms())) / as_f32(1000.0))
    interval = '-i'+format(seconds,'.1f')
    if variant == 'busybox':
        return [program,target.name,interval]+options.ping_args
    cmd = [program,'-O',interval]
    if options.interface is not None:
        cmd += ['-I',options.interface]
    return cmd+options.ping_args+[target.name]


def prepare_ping(targets, options):
    processes = []
    try:
        for target in targets:
            try:
                info = subprocess.run(['ping','-V'],stdin=subprocess.DEVNULL,
                                      stdout=subprocess.PIPE,stderr=subprocess.PIPE)
            except OSError as e:
                text = os_error(e)
                fail('Error spawning ping: '+text+'\n\nCaused by:\n    '+text)
            if b'iputils' in info.stdout:
                variant = 'iputils'
            elif b'BusyBox' in info.stderr:
                variant = 'busybox'
            else:
                fail('Could not detect ping. Stderr: '+rust_debug_lines(info.stderr)+'\nStdout: '+rust_debug_lines(info.stdout))
            try:
                process = subprocess.Popen(ping_arguments(target, options, variant),
                                           stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,
                                           stderr=subprocess.PIPE)
            except OSError as e:
                text = os_error(e)
                fail('Error spawning ping: '+text+'\n\nCaused by:\n    '+text)
            processes.append(process)
    except BaseException:
        for p in processes:
            stop_process(p)
        raise
    return processes


def stop_process(p):
    try:
        if p.poll() is None:
            p.kill()
        p.wait()
    except (OSError, ProcessLookupError):
        pass


class Terminal:
    def __init__(self, clear):
        self.clear = clear
        self.fd = None
        self.attrs = None
        self.width, self.height = 0,0

    def size(self):
        for fd in [1,self.fd,0]:
            if fd is None:
                continue
            try:
                s = os.get_terminal_size(fd)
                return s.columns,s.lines
            except OSError:
                pass
        return self.width,self.height

    def open(self):
        try:
            if os.isatty(0):
                self.fd = os.dup(0)
            else:
                self.fd = os.open('/dev/tty',os.O_RDWR | os.O_CLOEXEC)
            self.attrs = termios.tcgetattr(self.fd)
            tty.setraw(self.fd,termios.TCSANOW)
            self.width,self.height = self.size()
            self.write(ESC+'8;%d;%dt' % (self.height,self.width))
            if self.clear:
                self.write(ESC+'?1049h')
            self.write(ESC+'2J')
        except (OSError,termios.error) as e:
            if self.fd is not None:
                os.close(self.fd)
                self.fd = None
            fail(os_error(e))

    @staticmethod
    def write(text):
        sys.stdout.write(text)
        sys.stdout.flush()

    def close(self):
        if self.fd is None:
            return
        try:
            self.write(ESC+'?25h'+ESC+'%d;%dH' % (self.height+1,self.width+1))
            if self.clear:
                self.write(ESC+'?1049l')
        finally:
            try:
                termios.tcsetattr(self.fd,termios.TCSANOW,self.attrs)
            except (OSError,termios.error):
                pass
            os.close(self.fd)
            self.fd = None


def delay_uninterruptibly(seconds):
    # Long intervals remain valid without overflowing the platform sleep API.
    while seconds > 86400:
        time.sleep(86400)
        seconds -= 86400
    if seconds:
        time.sleep(seconds)


def command_worker(i, target, interval, events, stopping):
    while not stopping.is_set():
        begin = time.monotonic_ns()
        try:
            process = subprocess.Popen(target.command,stdin=subprocess.DEVNULL,
                                       stdout=subprocess.PIPE,stderr=subprocess.PIPE)
            process.communicate()
        except OSError as e:
            events.put(('error',i,os_error(e)))
            break
        done = time.monotonic_ns()
        value = (done-begin)//1000 if process.returncode == 0 else None
        events.put(('sample',i,done/1000000000,value))
        delay_uninterruptibly(interval)
    events.put(('done',i))


PING_TIME = re.compile(rb'time[=<]([0-9]+(?:\.[0-9]+)?)\s*ms')


def ping_worker(i, process, events, stopping):
    error_data = []
    def read_error():
        try:
            error_data.append(process.stderr.read())
        except (ValueError,OSError):
            pass
    error_reader = threading.Thread(target=read_error,daemon=True)
    error_reader.start()
    try:
        while not stopping.is_set():
            line = process.stdout.readline()
            if not line:
                break
            if stopping.is_set():
                break
            now = time.monotonic()
            match = PING_TIME.search(line)
            if match:
                value = max(0,int(float(match.group(1))*1000))
                events.put(('sample',i,now,value))
            elif line.startswith(b'no answer yet for icmp_seq='):
                events.put(('sample',i,now,None))
        if stopping.is_set():
            stop_process(process)
        else:
            status = process.wait()
            error_reader.join()
            if status:
                label = ('exit status: '+str(status)) if status >= 0 else ('signal: '+str(-status))
                stderr = b''.join(error_data).decode('utf-8',errors='replace')
                events.put(('log',i,'There was an error running ping: '+label+'\nStderr: '+stderr+'\n\n'))
    except (OSError,ValueError):
        stop_process(process)
    events.put(('done',i))


def quit_key(data):
    i = 0
    while i < len(data):
        c = data[i]
        if c in (3,ord('q')):
            return True
        if c == 27:
            if i+1 < len(data) and data[i+1] in (ord('['),ord('O')):
                # Cursor/function/mouse key sequences are ignored.
                i += 2
                while i < len(data) and not (64 <= data[i] <= 126):
                    i += 1
            elif i+1 < len(data):
                i += 1
            else:
                return True
        i += 1
    return False


def run(options, targets):
    processes = [] if options.cmd else prepare_ping(targets,options)
    terminal = Terminal(options.clear)
    try:
        terminal.open()
    except BaseException:
        for p in processes:
            stop_process(p)
        raise
    events = queue.Queue()
    stopping = threading.Event()
    threads = []
    # Wall and monotonic clocks are paired once, so local time labels advance
    # consistently with the sample timestamps.
    start = time.monotonic()
    wall_start = time.time()
    renderer = Renderer(options,targets,start,wall_start)
    try:
        for i,target in enumerate(targets):
            if options.cmd:
                fn = command_worker
                args = (i,target,options.interval_ms()/1000,events,stopping)
            else:
                fn = ping_worker
                args = (i,processes[i],events,stopping)
            worker = threading.Thread(target=fn,args=args,daemon=True)
            worker.start()
            threads.append(worker)
        next_frame = start+.25
        done = set()
        quitting = False
        while not quitting:
            while True:
                try:
                    event = events.get_nowait()
                except queue.Empty:
                    break
                kind,i,*data = event
                if kind == 'sample':
                    targets[i].record(*data)
                elif kind == 'error':
                    targets[i].error = data[0]
                elif kind == 'done':
                    done.add(i)
                elif kind == 'log':
                    sys.stderr.write(data[0])
                    sys.stderr.flush()
            if not options.cmd and len(done) == len(targets):
                break
            now = time.monotonic()
            if now >= next_frame:
                for target in targets:
                    target.prune(now-options.buffer)
                w,h = terminal.size()
                terminal.width,terminal.height = w,h
                terminal.write(renderer.draw(w,h,now))
                next_frame = now+.25
            wait = max(0,min(.02,next_frame-time.monotonic()))
            try:
                readable,_,_ = select.select([terminal.fd],[],[],wait)
                if readable:
                    keys = os.read(terminal.fd,4096)
                    if quit_key(keys):
                        quitting = True
            except InterruptedError:
                pass
    except KeyboardInterrupt:
        pass
    finally:
        stopping.set()
        terminal.close()
    # Closing the screen precedes joining the samplers, including a command that
    # was already running or a ping blocked waiting for its next output line.
    for thread in threads:
        thread.join()
    # The last pending errors can arrive after the user has requested shutdown.
    while True:
        try:
            event = events.get_nowait()
        except queue.Empty:
            break
        if event[0] == 'error':
            targets[event[1]].error = event[2]
    for target in targets:
        if target.error:
            fail(target.error)
    return 0
