"""A standalone implementation of an interactive latency graph."""
import sys

from cli import Exit, fail, parse
from model import targets_for
from engine import os_error, run


def main():
    try:
        options = parse()
        targets = targets_for(options)
        return run(options,targets)
    except Exit as e:
        out = sys.stdout if e.stdout else sys.stderr
        out.write(e.message)
        out.flush()
        return e.code
    except OSError as e:
        try:
            sys.stderr.write('Error: '+os_error(e)+'\n')
        except OSError:
            pass
        return 1
    except KeyboardInterrupt:
        return 130


if __name__ == '__main__':
    raise SystemExit(main())
