"""Terminal-aware styling for command-line help and diagnostics."""
import os
import re
import sys

from cli import PARAMS

RESET = '\x1b[0m'


def literal(text):
    return '\x1b[1m\x1b[96m'+text+RESET


def placeholder(text):
    return '\x1b[36m'+text+RESET


def heading(text):
    return '\x1b[1m\x1b[92m'+text+RESET


def warning(text):
    return '\x1b[1m\x1b[33m'+text+RESET


def enabled(stdout):
    if os.environ.get('NO_COLOR'):
        return False
    if os.environ.get('CLICOLOR_FORCE'):
        return True
    if os.environ.get('CLICOLOR') == '0':
        return False
    return os.isatty(1 if stdout else 2) and os.environ.get('TERM') != 'dumb'


def style_arguments(text):
    out = []
    i = 0
    while i < len(text):
        if text.startswith('<--',i):
            out.append(placeholder(text[i:]))
            break
        match = re.match(r'--[A-Za-z0-9-]+|-[A-Za-z0-9]',text[i:])
        if match:
            opt = match.group()
            out.append(literal(opt))
            i += len(opt)
            key = opt[2:] if opt.startswith('--') else ''
            if key in PARAMS:
                val = '<'+PARAMS[key]+'>'
                if text.startswith(' '+val,i):
                    out.extend((placeholder(' '),placeholder(val)))
                    i += 1+len(val)
            elif key == 'ping-args' and text.startswith(' [<PING_ARGS>...]',i):
                out.extend((placeholder(' ['),placeholder('<PING_ARGS>...'),placeholder(']')))
                i += len(' [<PING_ARGS>...]')
            continue
        match = re.match(r'\[OPTIONS\]|\[HOSTS_OR_COMMANDS\]\.\.\.|<HOSTS_OR_COMMANDS>\.\.\.',text[i:])
        if match:
            out.append(placeholder(match.group()))
            i += len(match.group())
            continue
        out.append(text[i])
        i += 1
    return ''.join(out)


def quoted(line, styles):
    i = 0
    def replace(m):
        nonlocal i
        style = styles[min(i,len(styles)-1)]
        i += 1
        return "'"+style(m.group(1))+"'"
    return re.sub(r"'([^']*)'",replace,line)


def colorize(message, stdout, code):
    if not enabled(stdout) or (code != 2 and not message.startswith('Ping, but with a graph.')):
        return message
    name = os.path.basename(sys.argv[0])
    lines = []
    for line in message.split('\n'):
        if line.startswith('Usage: '):
            rest = line[len('Usage: '):]
            if rest.startswith(name):
                tail = rest[len(name):]
            else:
                name,_,tail = rest.partition(' ')
                tail = ' '+tail
            line = heading('Usage:')+' '+literal(name)+style_arguments(tail)
        elif line in ('Arguments:','Options:'):
            line = heading(line)
        elif stdout and re.match(r'^\s{2,6}-',line):
            line = style_arguments(line)
        elif stdout and line.startswith('  [HOSTS_OR_COMMANDS]...'):
            part = '[HOSTS_OR_COMMANDS]...'
            line = '  '+placeholder(part)+line[len(part)+2:]
        elif line.startswith('error: '):
            text = line[7:]
            styles = [warning,literal] if text.startswith(('invalid value','unexpected value')) else [warning]
            line = '\x1b[1m\x1b[91merror:'+RESET+' '+quoted(text,styles)
        elif line.startswith('  tip: '):
            text = line[7:]
            styles = [warning,literal] if text.startswith('to pass ') else [literal]
            line = '  '+literal('tip:')+' '+quoted(text,styles)
        elif line.startswith('For more information,'):
            line = quoted(line,[literal])
        lines.append(line)
    return '\n'.join(lines)
